-- Associazione permessi/funzioni.
INSERT INTO ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM (CO_AUTH_PERMISSION_ID, CO_AUTH_FUNCTION_ID)
SELECT p.CO_ID, f.CO_ID FROM ${database.defaultSchemaName}.AUTH_PERMISSION p, ${database.defaultSchemaName}.AUTH_FUNCTION f
WHERE p.TE_NOME IN ('PERMISSION_CREATION', 'PERMISSION_MODIFICATION', 'PERMISSION_DELETION')
  AND f.TE_NOME = 'PERMISSION_MANAGEMENT'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

INSERT INTO ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM (CO_AUTH_PERMISSION_ID, CO_AUTH_FUNCTION_ID)
SELECT p.CO_ID, f.CO_ID FROM ${database.defaultSchemaName}.AUTH_PERMISSION p, ${database.defaultSchemaName}.AUTH_FUNCTION f
WHERE p.TE_NOME IN ('PERMISSION_LIST', 'PERMISSION_DETAIL')
  AND f.TE_NOME = 'PERMISSION_INQUIRY'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

INSERT INTO ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM (CO_AUTH_PERMISSION_ID, CO_AUTH_FUNCTION_ID)
SELECT p.CO_ID, f.CO_ID FROM ${database.defaultSchemaName}.AUTH_PERMISSION p, ${database.defaultSchemaName}.AUTH_FUNCTION f
WHERE p.TE_NOME IN ('GROUP_CREATION', 'GROUP_MODIFICATION', 'GROUP_DELETION', 'GROUP_MODIFICATION_FUNCTION_ASSOCIATION', 'GROUP_MODIFICATION_FUNCTION_DISASSOCIATION', 'FUNCTION_LIST_ASSOCIATED_WITH_GROUP', 'FUNCTION_LIST_ASSOCIABLE_WITH_GROUP')
  AND f.TE_NOME = 'GROUP_MANAGEMENT'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

INSERT INTO ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM (CO_AUTH_PERMISSION_ID, CO_AUTH_FUNCTION_ID)
SELECT p.CO_ID, f.CO_ID FROM ${database.defaultSchemaName}.AUTH_PERMISSION p, ${database.defaultSchemaName}.AUTH_FUNCTION f
WHERE p.TE_NOME IN ('GROUP_LIST', 'GROUP_DETAIL')
  AND f.TE_NOME = 'GROUP_INQUIRY'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

