WHERE p.TE_NOME IN ('USER_LIST', 'USER_DETAIL', 'GROUP_LIST')
  AND f.TE_NOME = 'USER_INQUIRY'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

INSERT INTO ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM (CO_AUTH_PERMISSION_ID, CO_AUTH_FUNCTION_ID)
