WHERE p.TE_NOME IN ('FUNCTION_CREATION', 'FUNCTION_MODIFICATION', 'FUNCTION_DELETION', 'FUNCTION_MODIFICATION_PERMISSION_ASSOCIATION', 'FUNCTION_MODIFICATION_PERMISSION_DISASSOCIATION', 'PERMISSION_LIST_ASSOCIATED_WITH_FUNCTION', 'PERMISSION_LIST_ASSOCIABLE_WITH_FUNCTION')
  AND f.TE_NOME = 'FUNCTION_MANAGEMENT'
  AND NOT EXISTS (SELECT 1 FROM ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM x WHERE x.CO_AUTH_PERMISSION_ID = p.CO_ID AND x.CO_AUTH_FUNCTION_ID = f.CO_ID);

INSERT INTO ${database.defaultSchemaName}.AUTH_FUN_AUTH_PERM (CO_AUTH_PERMISSION_ID, CO_AUTH_FUNCTION_ID)
