-- Abilitazione delle funzioni Auth ai gruppi amministrativi.
INSERT INTO ${database.defaultSchemaName}.AUTH_GROUP_AUTH_FUNC (CO_AUTH_FUNCTION_ID, CO_AUTH_GROUP_ID)
SELECT f.CO_ID, g.CO_ID FROM ${database.defaultSchemaName}.AUTH_FUNCTION f, ${database.defaultSchemaName}.AUTH_GROUP g
WHERE f.TE_NOME IN ('PERMISSION_MANAGEMENT', 'PERMISSION_INQUIRY', 'GROUP_MANAGEMENT', 'GROUP_INQUIRY', 'USER_MANAGEMENT', 'USER_INQUIRY', 'FUNCTION_MANAGEMENT', 'FUNCTION_INQUIRY')
  AND g.TE_NOME IN ('pagopa-p-adgroup-smo-kpi-psp-amministrativa', 'pagopa-p-adgroup-smo-payments-amministrativa', 'pagopa-p-adgroup-smo-kpi-prn-amministrativa')
